import "../AdoptionInfoHeader/AdoptionInfoHeader";
import AdoptionInfoHeader from "../AdoptionInfoHeader/AdoptionInfoHeader";
import "../FirstAdoptionInfoContainer/FirstAdoptionInfoContainer";
import FirstAdoptionInfoContainer from "../FirstAdoptionInfoContainer/FirstAdoptionInfoContainer";
import "../SecondAdoptionInfoContainer/SecondAdoptionInfoContainer";
import SecondAdoptionInfoContainer from "../SecondAdoptionInfoContainer/SecondAdoptionInfoContainer";
import "../ThirdAdoptionInfoContainer/ThirdAdoptionInfoContainer";
import ThirdAdoptionInfoContainer from "../ThirdAdoptionInfoContainer/ThirdAdoptionInfoContainer";

const AdoptionInfo = () => {
  return (
    <>
      <AdoptionInfoHeader />
      <FirstAdoptionInfoContainer />
      <SecondAdoptionInfoContainer />
      <ThirdAdoptionInfoContainer />
    </>
  );
};

export default AdoptionInfo;
